import{_ as o,o as t,c as i,ae as a}from"./chunks/framework.Czhw_PXq.js";const m=JSON.parse('{"title":"ADR 005: Google Auth Limitation in Production","description":"","frontmatter":{},"headers":[],"relativePath":"adr/005-google-auth-limitation.md","filePath":"adr/005-google-auth-limitation.md"}'),n={name:"adr/005-google-auth-limitation.md"};function r(s,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-005-google-auth-limitation-in-production" tabindex="-1">ADR 005: Google Auth Limitation in Production <a class="header-anchor" href="#adr-005-google-auth-limitation-in-production" aria-label="Permalink to &quot;ADR 005: Google Auth Limitation in Production&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h2><p>2026-03-04</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The project implements dual authentication methods: Email/Password (custom) and Google OAuth (via <code>@react-oauth/google</code>). The application is deployed on Render&#39;s free tier, using a shared subdomain (<code>.onrender.com</code>). Google&#39;s security policies for OAuth 2.0 (specifically Cross-Origin-Opener-Policy or COOP) require strict origin matching and often block popup/redirect flows on shared subdomains unless a verified custom domain (e.g., <code>www.myapp.com</code>) is used. This restriction causes the Google Sign-In popup to fail with a &quot;Policy Blocked&quot; error in the production environment, despite working perfectly in the development environment (<code>localhost</code>).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>For the scope of this Master&#39;s Thesis (TFM), we will:</p><ol><li><strong>Keep Google Auth code in the codebase</strong> to demonstrate technical proficiency and correct implementation.</li><li><strong>Acknowledge the limitation</strong> in production as an infrastructure constraint (lack of custom domain funding/scope).</li><li><strong>Use Email/Password</strong> as the primary, fully supported authentication method for the live demo.</li><li><strong>Provide Proof of Work</strong> (Video/Screenshots) showing Google Auth functioning in the local environment.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive:</strong> Reduces debugging time on infrastructure issues outside the project&#39;s core scope (AI analysis logic). ensuring the defense focuses on the working features.</li><li><strong>Negative:</strong> Users cannot use Google Sign-In on the live deployment.</li><li><strong>Mitigation:</strong> The login page clearly offers Email/Password Registration, which is fully functional.</li></ul><h2 id="proof-of-implementation" tabindex="-1">Proof of Implementation <a class="header-anchor" href="#proof-of-implementation" aria-label="Permalink to &quot;Proof of Implementation&quot;">​</a></h2><p>Video evidence of the working Google Auth flow in the local environment has been recorded and archived.</p>',14)])])}const p=o(n,[["render",r]]);export{m as __pageData,p as default};
